  workspace.querySelectorAll('form.hospital-discharge-ready').forEach((form) => form.addEventListener('submit', async (event) => { event.preventDefault(); const values = new FormData(form); try { await staffApi(`/api/v1/staff/hospital/admissions/${encodeURIComponent(form.dataset.admission)}`, 'PATCH', { action: 'READY_FOR_DISCHARGE', dischargeSummary: values.get('dischargeSummary') }); await loadStaff(); } catch (error) { window.alert(error.message); } }));
