  workspace.querySelectorAll('form.document-generate').forEach((form) => form.addEventListener('submit', async (event) => { event.preventDefault(); const values = new FormData(form); try { await staffApi('/api/v1/staff/documents', 'POST', { ownerId: form.dataset.owner, petId: form.dataset.pet, appointmentId: form.dataset.appointment || undefined, invoiceId: form.dataset.invoice, kind: values.get('kind') }); await loadStaff(); } catch (error) { window.alert(error.message); } }));
  workspace.querySelectorAll('[data-crm-task]').forEach((button) => button.addEventListener('click', async () => { const title = window.prompt('Что нужно сделать?'); if (!title) return; const dueAt = window.prompt('Когда напомнить? Например 2026-08-20 12:00 (можно оставить пустым)'); try { await staffApi('/api/v1/staff/crm/tasks', 'POST', { ownerId: button.dataset.crmTask, petId: button.dataset.pet || undefined, title, kind: 'FOLLOW_UP', priority: 'NORMAL', dueAt: dueAt ? new Date(dueAt).toISOString() : undefined }); await loadStaff(); } catch (error) { window.alert(error.message); } }));
  workspace.querySelectorAll('[data-crm-contact]').forEach((button) => button.addEventListener('click', async () => { const message = window.prompt('Кратко зафиксируйте, о чём поговорили или что сообщили владельцу.'); if (!message) return; const channel = window.prompt('Канал: PHONE, TELEGRAM, EMAIL, SMS или IN_APP', 'PHONE'); if (!channel) return; try { await staffApi('/api/v1/staff/crm/communications', 'POST', { ownerId: button.dataset.crmContact, petId: button.dataset.pet || undefined, body: message, channel, direction: 'OUTBOUND', kind: 'FOLLOW_UP' }); await loadStaff(); } catch (error) { window.alert(error.message); } }));
  workspace.querySelectorAll('[data-crm-marketing]').forEach((button) => button.addEventListener('click', async () => { const enabled = button.dataset.enabled !== 'true'; if (!window.confirm(enabled ? 'Зафиксировать согласие на маркетинговые сообщения?' : 'Отключить маркетинговые сообщения для владельца?')) return; try { await staffApi(`/api/v1/staff/crm/owners/${encodeURIComponent(button.dataset.crmMarketing)}`, 'PATCH', { marketingConsent: enabled }); await loadStaff(); } catch (error) { window.alert(error.message); } }));
  workspace.querySelectorAll('[data-crm-task-done]').forEach((button) => button.addEventListener('click', async () => { button.disabled = true; try { await staffApi(`/api/v1/staff/crm/tasks/${encodeURIComponent(button.dataset.crmTaskDone)}`, 'PATCH', { state: 'DONE' }); await loadStaff(); } catch (error) { window.alert(error.message); button.disabled = false; } }));
  workspace.querySelector('#staff-search')?.addEventListener('submit', async (event) => { event.preventDefault(); const target = workspace.querySelector('#staff-search-results'); const q = new FormData(event.currentTarget).get('q'); try { const result = await staffApi(`/api/v1/staff/search?q=${encodeURIComponent(q)}`); target.innerHTML = result.results.length ? result.results.map((item) => `<span style="display:inline-flex;margin:0 6px 6px 0;padding:7px 9px;border-radius:8px;background:#edf0ec;font-size:11px"><b>${staffEscape(item.title)}</b>&nbsp;· ${staffEscape(item.subtitle)}</span>`).join('') : '<small style="color:var(--muted)">Ничего не найдено.</small>'; } catch (error) { target.textContent = error.message; } });
  workspace.querySelector('#growth-package-create')?.addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; const values = new FormData(form); try { await staffApi('/api/v1/staff/growth/packages', 'POST', { name: values.get('name'), description: values.get('description'), credits: Number(values.get('credits')), priceMinor: Math.round(Number(values.get('price')) * 100), validityDays: Number(values.get('validityDays')), familyShared: values.get('familyShared') === 'on', serviceIds: values.getAll('serviceIds') }); await loadStaff(); } catch (error) { window.alert(error.message); } });
  const packageGrantForm = workspace.querySelector('#growth-package-grant');
  packageGrantForm?.querySelector('[name="ownerId"]')?.addEventListener('change', (event) => { const petSelect = packageGrantForm.querySelector('[name="petId"]'); [...petSelect.options].slice(1).forEach((option) => { option.disabled = option.dataset.owner !== event.currentTarget.value; }); if (petSelect.selectedOptions[0]?.disabled) petSelect.value = ''; });
  workspace.querySelector('#growth-package-grant')?.addEventListener('submit', async (event) => { event.preventDefault(); const values = new FormData(event.currentTarget); try { await staffApi(`/api/v1/staff/growth/packages/${encodeURIComponent(values.get('packageId'))}/grant`, 'POST', { ownerId: values.get('ownerId'), petId: values.get('petId') || undefined }); await loadStaff(); } catch (error) { window.alert(error.message); } });
