  workspace.querySelector('#growth-membership-enroll')?.addEventListener('submit', async (event) => { event.preventDefault(); const values = new FormData(event.currentTarget); try { await staffApi(`/api/v1/staff/growth/membership-plans/${encodeURIComponent(values.get('planId'))}/enroll`, 'POST', { ownerId: values.get('ownerId'), autoRenew: values.get('autoRenew') === 'on' }); await loadStaff(); } catch (error) { window.alert(error.message); } });
